</style></head><body><div class="w">
<div class="topo">
  <div>${a.video ? `<video controls playsinline preload="metadata" poster="${esc(capa)}" src="${esc(a.video)}"></video>` : (capa ? `<img src="${esc(capa)}" alt="" style="width:100%;border-radius:18px">` : '')}</div>
