    <div class="bts">
      ${wa ? `<a class="bt wa" href="${esc(wa)}" target="_blank" rel="noopener" data-ev="whatsapp">💬 Chamar no WhatsApp</a>` : ''}
      ${a.instagram ? `<a class="bt" href="https://instagram.com/${esc(a.instagram)}" target="_blank" rel="noopener">📸 @${esc(a.instagram)}</a>` : ''}
      ${mapa ? `<a class="bt" href="${esc(mapa)}" target="_blank" rel="noopener">📍 Como chegar</a>` : ''}
